import { useMemo, useState, type FormEvent } from 'react';
import { Alert, Button, Select, Switch, TextField } from '@jinx-ui/react';

type Role = 'member' | 'admin' | 'owner';

const ROLE_OPTIONS: { value: Role; label: string }[] = [
  { value: 'member', label: 'Участник' },
  { value: 'admin', label: 'Администратор' },
  { value: 'owner', label: 'Владелец' },
];

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

export default function TeamInviteForm() {
  const [email, setEmail] = useState('');
  const [emailTouched, setEmailTouched] = useState(false);
  const [role, setRole] = useState<Role>('member');
  const [notify, setNotify] = useState(true);
  const [submitted, setSubmitted] = useState(false);

  const isEmailValid = useMemo(() => EMAIL_PATTERN.test(email.trim()), [email]);
  const showEmailError = emailTouched && email.length > 0 && !isEmailValid;
  const canSubmit = isEmailValid;

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    setEmailTouched(true);
    if (!canSubmit) return;
    setSubmitted(true);
  };

  const handleEmailChange = (value: string) => {
    setEmail(value);
    setSubmitted(false);
  };

  return (
    <div className="jx-stack" style={{ gap: 'var(--jx-space-4)', maxWidth: 420 }}>
      {submitted ? (
        <Alert variant="success" onClose={() => setSubmitted(false)}>
          Приглашение отправлено на {email.trim()}
        </Alert>
      ) : null}

      <form
        className="jx-stack"
        style={{ gap: 'var(--jx-space-4)' }}
        onSubmit={handleSubmit}
        noValidate
      >
        <TextField
          label="Email"
          type="email"
          value={email}
          onChange={(event) => handleEmailChange(event.target.value)}
          onBlur={() => setEmailTouched(true)}
          placeholder="name@company.com"
          hint={
            showEmailError
              ? 'Введите адрес в формате name@company.com'
              : 'На этот адрес придёт приглашение в команду'
          }
          error={showEmailError}
          required
        />

        <Select
          label="Роль"
          value={role}
          onChange={(value) => setRole(value as Role)}
          options={ROLE_OPTIONS}
        />

        <Switch
          checked={notify}
          onChange={setNotify}
          label="Отправить уведомление"
        />

        <Button type="submit" disabled={!canSubmit}>
          Отправить приглашение
        </Button>
      </form>
    </div>
  );
}

